import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzTreeSelectModule } from 'ng-zorro-antd/tree-select';
import { NzTreeNodeOptions } from 'ng-zorro-antd/core/tree';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-tree-select — CVA, nodes-driven, single/multiple. */
@Component({
  selector: 'hrm-tree-select',
  imports: [FormsModule, NzTreeSelectModule],
  template: `
    <nz-tree-select
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzNodes]="nodes()"
      [nzPlaceHolder]="placeholder()"
      [nzMultiple]="multiple()"
      [nzAllowClear]="allowClear()"
      [nzShowSearch]="showSearch()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"></nz-tree-select>
  `,
  host: { class: 'hrm-tree-select', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmTreeSelect), multi: true }],
})
export class HrmTreeSelect extends HrmControl<string | string[]> {
  readonly nodes = input<NzTreeNodeOptions[]>([]);
  readonly placeholder = input('');
  readonly multiple = input(false);
  readonly allowClear = input(true);
  readonly showSearch = input(true);
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
}
